$:set -euo pipefail
cat AGENTS.md >/dev/null
if test -f README.md; then cat README.md >/dev/null; fi
gh api repos/BestNameYet/Terminals/issues/3 --jq .body >/dev/null
printf 'REMOTE_MAIN '; gh api repos/BestNameYet/Terminals/git/ref/heads/main --jq .object.sha
printf 'REMOTE_FILE_SHA '; gh api repos/BestNameYet/Terminals/contents/.devcontainer/devcontainer.json --jq .sha
cmp <(gh api repos/BestNameYet/Terminals/contents/.devcontainer/devcontainer.json --jq .content | base64 -d) <(cat <<'EXPECTED_CONTENT_EOF'
{
  "name": "MCP Remote Server Space",
  "features": {
    "ghcr.io/devcontainers/features/node:1": {
      "version": "lts"
    }
  },
  "forwardPorts":,
  "portsAttributes": {
    "3000": {
      "label": "MCP SSE Server",
      "onAutoForward": "silent",
      "elevationRequired": false
    }
  },
  "postCreateCommand": "npm install -g @modelcontextprotocol/server-everything",
  "waitFor": "postCreateCommand"
}
EXPECTED_CONTENT_EOF
)
printf 'EXACT_BYTES_MATCH yes\n'
printf 'REMOTE_FILE_BODY_BEGIN\n'
gh api repos/BestNameYet/Terminals/contents/.devcontainer/devcontainer.json --jq .content | base64 -d
printf 'REMOTE_FILE_BODY_END\n'
